package customer
import "context"
type Customer struct { ID, Email string }
type Store interface { Find(context.Context, string) (Customer, error) }
func Resolve(ctx context.Context, store Store, data string) (Customer, error) {
    record, err := store.Find(ctx, data)
    if err != nil { return Customer{}, err }
    return record, nil
}
func LookupEmail(ctx context.Context, store Store, lookupKey string) (string, error) {
    record, err := Resolve(ctx, store, lookupKey)
    if err != nil { return "", err }
    return record.Email, nil
}

