package delivery
type Sink interface { Audit(string); Emit(string) error }
func Publish(s Sink, enabled bool, body string) error {
    s.Audit(body)
    if enabled {
        if body != "" {
            return s.Emit(body)
        } else {
            return nil
        }
    } else {
        return nil
    }
}
func IsAllowed(enabled, paused bool) bool {
    return enabled && !paused
}

