package importer
import ("context"; "fmt"; "strconv"; "strings")
type Customer struct { Name, Email, Region string; Age int }
type Store interface { Save(context.Context, Customer) error }
func Load(ctx context.Context, rows [][]string, store Store) error {
    for _, row := range rows {
        if len(row) != 4 { return fmt.Errorf("expected four fields") }
        name := strings.TrimSpace(row[0])
        email := strings.ToLower(strings.TrimSpace(row[1]))
        age, err := strconv.Atoi(strings.TrimSpace(row[2]))
        if err != nil { return fmt.Errorf("parse age: %w", err) }
        region := strings.ToUpper(strings.TrimSpace(row[3]))
        if region == "" { region = "UNKNOWN" }
        customer := Customer{Name: name, Email: email, Age: age, Region: region}
        if err := store.Save(ctx, customer); err != nil { return err }
    }
    return nil
}
func NormalizeRegion(raw string) string {
    value := strings.TrimSpace(raw)
    value = strings.ToUpper(value)
    if value == "" { return "UNKNOWN" }
    return value
}

