package exporter
import ("net/url"; "sort"; "strings")
type Row struct { Address string }
type Writer interface { WriteAddress(string) error }
func Export(row Row, writer Writer) error {
    data := row.Address
    data = strings.TrimSpace(data)
    data = strings.ToUpper(data)
    data = url.QueryEscape(data)
    return writer.WriteAddress(data)
}
func SortInPlace(keys []string) {
    sort.Strings(keys)
}
func FirstSortedKey(keys []string) string {
    SortInPlace(keys)
    if len(keys) == 0 { return "" }
    return keys[0]
}

