type Store interface { Read(context.Context, string) ([]byte, error) }
type RemoteClient interface { Get(context.Context, string) ([]byte, error) }
type RemoteStore struct { Client RemoteClient }
func (s RemoteStore) Read(ctx context.Context, key string) ([]byte, error) {
    data, err := s.Client.Get(ctx, key)
