package invoice
import ("context"; "time")
type Invoice struct { ID string }
type DeliveryOptions struct { NotifyCustomer, ForceResend bool }
type Sender interface { Send(context.Context, Invoice, DeliveryOptions) error }
func sendInvoice(ctx context.Context, sender Sender, invoice Invoice, notify bool, force bool) error {
    return sender.Send(ctx, invoice, DeliveryOptions{NotifyCustomer: notify, ForceResend: force})
}
func OnCheckout(ctx context.Context, sender Sender, invoice Invoice) error {
    return sendInvoice(ctx, sender, invoice, true, false)
}
func RetryManually(ctx context.Context, sender Sender, invoice Invoice) error {
    return sendInvoice(ctx, sender, invoice, false, true)
}
type Client struct { BaseURL string; Timeout time.Duration }
func NewClient(baseURL string, timeout time.Duration) Client { return Client{BaseURL: baseURL, Timeout: timeout} }

