package queue
type Settings struct { Queue string; Retries, Burst int }
func queueName(tier string) string {
    switch tier { case "priority": return "fast"; case "standard": return "normal"; default: return "slow" }
}
func retryLimit(tier string) int {
    switch tier { case "priority": return 6; case "standard": return 3; default: return 1 }
}
func burstSize(tier string) int {
    switch tier { case "priority": return 20; case "standard": return 10; default: return 2 }
}
func ForTier(tier string) Settings { return Settings{queueName(tier), retryLimit(tier), burstSize(tier)} }

